import React, { useEffect, useState } from "react";
import { useParams } from "react-router-dom";
import { getById } from "../services/schemeService";

const SchemeDetails = () => {

    const { id } = useParams();
    const [scheme, setScheme] = useState(null);

    useEffect(() => {
        fetchScheme();
    }, []);

    const fetchScheme = async () => {
        const data = await getById(id);
        setScheme(data);
    };

    if (!scheme) return <h2>Loading...</h2>;

    return (
        <div className="details-container">
        <h2>{scheme.schemeName}</h2>

            <img
                src={process.env.PUBLIC_URL + scheme.image}
                alt={scheme.schemeName}
                style={{ width: "100%", maxWidth: "500px" }}
            />

            <p><strong>Category:</strong> {scheme.category}</p>
            <p><strong>State:</strong> {scheme.state}</p>
            <p><strong>Description:</strong> {scheme.description}</p>
            <p><strong>Eligibility:</strong> {scheme.eligibility}</p>
            <p><strong>Benefits:</strong> {scheme.benefits}</p>
            <p><strong>Required Documents:</strong> {scheme.requiredDocuments}</p>

            <a
                href={scheme.officialLink}
                target="_blank"
                rel="noreferrer"
                className="btn"
            >
                Apply on Official Website
            </a>
        </div>
    );
};

export default SchemeDetails;
